const safeLink=value=>{try{const u=new URL(value);return u.protocol==='https:'?u.href:''}catch{return ''}};
const profileAvatar=t=>t.pfp?`<img src="${esc(t.pfp)}" alt="${esc(t.name)} profile picture">`:esc(t.symbol);
const liquidityOf=t=>t.status==='draft'?0:({1:12800,2:4600,3:48200,4:2700,5:16300,6:5200,7:36200,8:3900}[t.id]||0);
function candlePreview(t){if(t.status==='draft')return '<div class="draft-chart">NO MARKET YET<span>Chart appears after launch</span></div>';const data=MarketDemo.series(t.id,5,30),lo=Math.min(...data.map(d=>d.low)),hi=Math.max(...data.map(d=>d.high)),y=p=>70-(p-lo)/(hi-lo)*58;return `<svg class="card-candles" viewBox="0 0 270 90" preserveAspectRatio="none" aria-label="Sample candlestick chart, not live market data"><path d="M0 20H270M0 45H270M0 70H270M45 0V90M90 0V90M135 0V90M180 0V90M225 0V90" stroke="#233a59" stroke-width=".5"/>${data.map((d,i)=>{const x=i*9+4,color=d.close>=d.open?'#78adff':'#dd8da7';return `<g class="${i===29?'last-candle':''}"><path d="M${x} ${y(d.high)}V${y(d.low)}" stroke="${color}"/><rect x="${x-2.5}" y="${Math.min(y(d.open),y(d.close))}" width="5" height="${Math.max(1,Math.abs(y(d.open)-y(d.close)))}" fill="${color}"/></g>`}).join('')}</svg>`}
render=function(){let list=tokens.filter(t=>(view!=='watchlist'||saved.includes(t.id))&&(filter==='all'||t.status===filter)&&(`${t.name} ${t.ticker}`).toLowerCase().includes($('#search').value.toLowerCase()));const sort=$('#sort').value;if(sort==='cap'||sort==='volume')list.sort((a,b)=>b[sort]-a[sort]);if(sort==='new')list.sort((a,b)=>b.id-a.id);$('#marketTitle').innerHTML=`${view==='watchlist'?'Your watchlist':'Discover tokens'}<span class="count">${list.length}</span>`;$('#grid').innerHTML=list.length?list.map(t=>`<article class="token pixel-market-card" tabindex="0" role="button" aria-label="Open ${esc(t.name)} token page" data-id="${t.id}"><div class="pixel-card-inner"><div class="token-top"><div class="avatar" style="--art:${t.art}">${profileAvatar(t)}</div><div><h3>${esc(t.name)}</h3><span class="ticker">${esc(t.ticker)} / USDC</span></div><button class="star ${saved.includes(t.id)?'saved':''}" data-save="${t.id}" aria-label="${saved.includes(t.id)?'Remove from':'Add to'} watchlist" aria-pressed="${saved.includes(t.id)}">${saved.includes(t.id)?'★':'☆'}</button></div><p class="token-desc">${esc(t.desc)}</p><div class="card-chart-header"><span>${t.status==='draft'?'PRE-LAUNCH':'5M CANDLES'}</span><span class="demo-chip">${t.status==='draft'?'DRAFT':t.status==='live'?'ON-CHAIN POOL':'DEMO · NOT LIVE'}</span></div>${candlePreview(t)}<div class="card-metric-grid"><div><span>MARKET CAP · USDC</span><b>${fmt(t.cap)}</b></div><div><span>USDC LIQUIDITY</span><b>${fmt(liquidityOf(t))}</b></div><div><span>24H VOL · USDC</span><b>${fmt(t.volume)} <small class="${t.change<0?'negative':'positive'}">${t.change>0?'+':''}${t.change}%</small></b></div><div><span>MINTED</span><b class="mint-age">${t.status==='draft'?'Not minted':esc(t.age)+' ago'}</b></div></div><div class="progress-meta"><span>${t.status==='draft'?'LAUNCH DRAFT':t.status==='live'?'DIRECT USDC POOL':t.status==='graduated'?'GRADUATED ':'BONDING CURVE'}</span><b>${t.progress}%</b></div><div class="pixel-segments">${Array.from({length:20},(_,i)=>`<i class="${i<t.progress/5?'filled':''}"></i>`).join('')}</div><div class="pixel-card-foot"><span>♜ THE MINT <b>0.75%</b></span><span>OPEN </span></div></div></article>`).join(''):'<div class="empty">No matching tokens. Try another search or filter.</div>';$$('[data-save]').forEach(b=>b.onclick=e=>{e.stopPropagation();const id=Number(b.dataset.save);saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];write('bluemint-watch',saved);render()});$$('.token').forEach(el=>{el.onclick=()=>detail(Number(el.dataset.id));el.onkeydown=e=>{if(e.target===el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.click()}}})};$('#search').oninput=render;$('#sort').onchange=render;
let launchPfp='';function openCreate(){location.hash='create';if(location.hash==='#create')showCreate()}$('#launch').onclick=openCreate;$('#launchBottom').onclick=openCreate;
function showCreate(){if(chartObserver){chartObserver.disconnect();chartObserver=null}homeMain.hidden=true;detailMain.hidden=false;document.title='Create Launch — BlueMint';launchPfp='';detailMain.innerHTML=`<div class="token-breadcrumb"><a href="#">← Discover</a><span>/</span><span>Create launch</span><span class="mint-demo-pill">LOCAL DRAFT MODE</span></div><div class="create-heading"><div><span class="eyebrow blue">YOUR TOKEN STARTS HERE</span><h1>Create your launch.</h1><p>Give your token an identity. Build its market in USDC.</p></div><span class="create-step">01 / CONFIGURE → 02 / REVIEW → 03 / SAVE</span></div><div class="create-layout"><form id="createForm" class="create-form"><section class="form-section"><h2><span>01</span> Token identity</h2><label class="pfp-upload" for="pfpFile"><span id="pfpPreview">＋</span><span><b>Upload token PFP</b><small>PNG, JPG or WebP · max 256 KB<br>Square image recommended</small></span><input id="pfpFile" type="file" accept="image/png,image/jpeg,image/webp" required></label><p id="pfpError" class="field-error" role="alert"></p><div class="form-grid"><label class="field">Token name<input name="name" maxlength="32" placeholder="e.g. Blue Hour" required></label><label class="field">Ticker<input name="ticker" maxlength="10" pattern="[A-Za-z0-9]{2,10}" placeholder="e.g. HOUR" required></label></div><label class="field">Description<textarea name="desc" maxlength="160" placeholder="Tell the world what you’re launching." required></textarea></label></section><section class="form-section"><h2><span>02</span> Official links</h2><p class="form-help">These links will be attached to this token’s page when you save. They cannot be edited through this preview.</p><label class="field">Twitter / X link <small>Optional</small><input name="twitter" type="url" placeholder="https://x.com/yourtoken"></label><label class="field">Website link <small>Optional</small><input name="website" type="url" placeholder="https://yourtoken.com"></label><div class="identity-lock">▣ Identity pinned to the saved token page.<span>This is an app-level draft record, not immutable on-chain metadata.</span></div></section><section class="form-section"><h2><span>03</span> USDC market & fees</h2><div class="form-grid"><label class="field">Quote asset<input value="Circle USDC · Solana" readonly></label></div><div class="split"><span>Developer buy → liquidity</span><b>50% of developer budget</b></div><div class="split"><span>Launchpad treasury</span><b>0.50%</b></div><div class="split"><span>Token’s Mint allocation</span><b>0.75%</b></div><div class="split"><span>Total launchpad fee</span><b>1.25% + Raydium fees</b></div><p class="form-help">50% of the developer’s USDC buy amount is allocated to this token’s liquidity. No separate liquidity commitment. Launch transactions stay disabled until the vault is qualified and deployed; saving a draft moves no funds.</p></section><label class="create-consent"><input name="confirm" type="checkbox" required><span>I understand this saves a device-local draft. No token will be minted and no funds will move.</span></label><p id="createError" class="field-error" role="alert"></p><button class="primary full" type="submit">Review launch →</button></form><aside class="create-sidebar"><section class="create-preview"><span class="eyebrow blue">YOUR TOKEN PREVIEW</span><div class="create-preview-top"><div class="avatar" id="liveAvatar">?</div><div><h3 id="liveName">Your token</h3><span id="liveTicker">TICKER / USDC</span></div></div><p id="liveDesc">Your community’s next chapter starts here.</p><div class="draft-chart">AWAITING LAUNCH<span>Candles appear once a market exists</span></div><div class="split"><span>Quote currency</span><b>USDC</b></div><div class="split"><span>Status</span><b>Not minted</b></div></section><section class="create-mint"><div class="mint-panel-heading"><div><span class="eyebrow blue">♜ THE MINT</span><h3>Your liquidity treasury.</h3></div></div><picture><source media="(prefers-reduced-motion: reduce)" srcset="assets/mint-vault.png"><img src="assets/mint-vault.gif" alt="Animated pixel treasury safe receiving USDC coins"></picture><div class="create-mint-copy"><b>50% of developer buy → liquidity</b><p>Plus 60% of net creator-fee receipts, after Raydium’s protocol share. Vault deployment is pending. No holder rewards.</p><span>CONCEPT ANIMATION · NOT LIVE</span></div></section></aside></div>`;
const form=$('#createForm');form.oninput=()=>{$('#liveName').textContent=form.elements.name.value||'Your token';$('#liveTicker').textContent=(form.elements.ticker.value.toUpperCase()||'TICKER')+' / USDC';$('#liveDesc').textContent=form.elements.desc.value||'Your community’s next chapter starts here.'};$('#pfpFile').onchange=async e=>{launchPfp='';const file=e.target.files[0];$('#pfpError').textContent='';if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>256*1024){$('#pfpError').textContent='Choose a PNG, JPG or WebP under 256 KB.';e.target.value='';return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{launchPfp=reader.result;$('#pfpPreview').innerHTML=`<img src="${launchPfp}" alt="Selected profile picture">`;$('#liveAvatar').innerHTML=`<img src="${launchPfp}" alt="Token preview">`};img.onerror=()=>{$('#pfpError').textContent='This image could not be read.';e.target.value=''};img.src=reader.result};reader.readAsDataURL(file)};form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),twitter=f.get('twitter').trim(),website=f.get('website').trim();if(!launchPfp){$('#createError').textContent='Upload a valid profile image first.';return}if((twitter&&(!safeLink(twitter)||!['x.com','www.x.com','twitter.com','www.twitter.com'].includes(new URL(twitter).hostname)))||(website&&!safeLink(website))){$('#createError').textContent='Use HTTPS links. The Twitter link must be on x.com or twitter.com.';return}const requestKey=crypto.randomUUID();const values={name:f.get('name').trim(),ticker:f.get('ticker').toUpperCase(),desc:f.get('desc').trim(),twitter:safeLink(twitter),website:safeLink(website),pfp:launchPfp};if(!values.name||!values.desc){$('#createError').textContent='Enter a name and description.';return}open(`<div class="eyebrow blue">REVIEW YOUR LAUNCH DRAFT</div><h2>${esc(values.name)} <span class="ticker">${esc(values.ticker)}</span></h2><div class="split"><span>Quote</span><b>Circle USDC</b></div><div class="split"><span>Developer buy → liquidity</span><b>50% of developer budget</b></div><div class="split"><span>Launchpad fee</span><b>1.25% + Raydium</b></div><div class="info-box">PFP, name, ticker and links will be pinned to this saved draft. No on-chain mint or enforceable metadata lock is created.</div>${values.ticker==='USDC'?'<p class="modal-sub">Your token’s USDC ticker does not make it Circle USDC or dollar-pegged.</p>':''}<button id="saveLaunch" class="primary full">Save draft & open token page </button>`);$('#saveLaunch').onclick=async()=>{let t={...values,id:Date.now(),symbol:values.ticker[0],art:'linear-gradient(135deg,#448cff,#142d62)',cap:0,volume:0,change:0,progress:0,age:'Draft',status:'draft',createdAt:new Date().toISOString(),profilePinned:true};if(window.BlueMintBackend?.enabled){try{$('#saveLaunch').disabled=true;t=await window.BlueMintBackend.saveLaunch({...values,requestKey});tokens.unshift(t);modal.close();render();location.hash='token/'+t.id;toast('Launch profile saved to the registry. No token minted.');return}catch(error){$('#saveLaunch').disabled=false;toast(error.message);return}}try{write('bluemint-drafts',[t,...drafts])}catch{$('#saveLaunch').insertAdjacentHTML('beforebegin','<p class="field-error">Device storage is full. Try a smaller image.</p>');return}drafts.unshift(t);tokens.unshift(t);modal.close();render();location.hash='token/'+t.id;toast('Draft saved. Profile pinned to your token page.')}}}
const previousRenderPage=renderPage;renderPage=function(t){previousRenderPage(t);if(t.pfp){$('.token-identity .avatar').innerHTML=profileAvatar(t)}const info=document.createElement('div');info.className='token-profile-links';info.innerHTML=`<span>${t.profilePinned?'▣ SAVED IDENTITY':'SAMPLE TOKEN'}</span>${safeLink(t.twitter)?`<a href="${esc(safeLink(t.twitter))}" target="_blank" rel="noopener noreferrer">Twitter / X </a>`:''}${safeLink(t.website)?`<a href="${esc(safeLink(t.website))}" target="_blank" rel="noopener noreferrer">Website </a>`:''}<span>${t.status==='draft'?'Not minted · no contract address':`Mint age: ${esc(t.age)} · sample`}</span>`;$('.token-heading').after(info);if(t.status==='draft'){$('.chart-panel').innerHTML='<div class="empty"><h2>Your market starts at launch.</h2><p>This is a saved draft. No candles, liquidity, trades or mint address exist yet.</p></div>';if(chartObserver){chartObserver.disconnect();chartObserver=null}$('#pagePrice').textContent='Not minted';activity('about')}};
const oldActivity=activity;activity=function(tab){if(selected.status==='draft'&&tab==='trades'){$('#activityContent').innerHTML='<div class="empty">No transactions. This token has not been minted.</div>';return}oldActivity(tab);if(tab==='about'&&selected.profilePinned){$('#activityContent').insertAdjacentHTML('beforeend',`<div class="info-box profile-note">Identity saved ${esc(new Date(selected.createdAt).toLocaleString())}. PFP and official links are attached to this draft. They are not locked on-chain.</div>`)}};
